const schools={holy:{tag:'PROTECTION · RESTORATION · RESTRAINT',title:'Hold back the darkness.',description:'Heal wounds, strengthen your defenses and bind enemies with light. Holy magic offers a way to endure when the realm pushes back.',spells:['Lesser Heal','Holy Armor','Binding Light'],note:'Binding Light restrains movement; a rooted enemy can still turn and attack.',image:'insc-holy-bindinglight.jpg',alt:'Development capture of the Holy Binding Light inscription'},blood:{tag:'SACRIFICE · SPEED · POWER',title:'Power drawn from sacrifice.',description:'Blood magic turns sacrifice into strength. Bolster your body, rush across the battlefield and send a rupture through the enemies ahead.',spells:['Blood Offering','Blood Rush','Blood Rupture'],note:'Blood spells can consume health. Read the cost before you commit.',image:'insc-blood-bloodrupture.jpg',alt:'Development capture of the Blood Rupture inscription'},dark:{tag:'FEAR · CURSES · THE VOID',title:'Reach into the forbidden.',description:'Unsettle your enemies with fear, lay a curse upon them, or bend an encounter with the power of the void. Dark magic changes how you control a fight.',spells:['Curse','Fear','Void Stasis'],note:'Carrying a Relief grants access to its school; each ability still has its own requirements.',image:'insc-dark-voidstasis.jpg',alt:'Development capture of the Dark Void Stasis inscription'}};
document.querySelectorAll('[data-school]').forEach(button=>button.addEventListener('click',()=>{const data=schools[button.dataset.school];document.querySelectorAll('[data-school]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));for(const [id,key] of [['school-tag','tag'],['school-title','title'],['school-description','description'],['school-note','note']])document.getElementById(id).textContent=data[key];document.getElementById('spells').replaceChildren(...data.spells.map(name=>{const s=document.createElement('span');s.textContent=name;return s}));const img=document.getElementById('school-image');img.src='assets/'+data.image;img.alt=data.alt;}));
